import regex as re
import glob
import os
from openpyxl import load_workbook

# Agent Name: architect
# Step Number: 0
# Reason for Mistake: The replacement r'\\"' is interpreted by the regex engine
# as one literal backslash followed by a quote, not two literal backslashes.

def task_func(directory_path='./xlsx_files/'):
    processed_count = 0
    files = glob.glob(os.path.join(directory_path, "*.xlsx"))

    for filename in files:
        workbook = None
        try:
            workbook = load_workbook(filename)
            modified = False

            for worksheet in workbook.worksheets:
                for row in worksheet.iter_rows():
                    for cell in row:
                        if isinstance(cell.value, str):
                            new_value = re.sub(
                                r'"',
                                lambda _: "\\\\" + '"',
                                cell.value
                            )
                            if new_value != cell.value:
                                cell.value = new_value
                                modified = True

            if modified:
                workbook.save(filename)

            processed_count += 1
        except Exception:
            continue
        finally:
            if workbook is not None:
                try:
                    workbook.close()
                except Exception:
                    pass

    return processed_count
